<script setup>
import {onMounted,ref} from 'vue'
const API_BASE=import.meta.env.VITE_API_BASE_URL||'http://localhost:8000/api/v1'
const bots=ref([]),botId=ref(''),commands=ref([]),flows=ref([]),loading=ref(true),saving=ref(false),error=ref(''),success=ref('')
async function req(path,options={}){const r=await fetch(`${API_BASE}${path}`,{credentials:'include',headers:{'Content-Type':'application/json'},...options});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof p.detail==='string'?p.detail:`Request failed (${r.status})`);return p}
function blank(){return {command:'',description:'',flow_id:null,enabled:true}}
async function loadBots(){loading.value=true;error.value='';try{bots.value=await req('/telegram/bots');if(bots.value.length){botId.value=String(bots.value[0].id);await load()}}catch(e){error.value=e.message}finally{loading.value=false}}
async function load(){if(!botId.value)return;loading.value=true;error.value='';success.value='';try{const [c,f]=await Promise.all([req(`/telegram/bots/${botId.value}/commands`),req(`/telegram/bots/${botId.value}/command-flows`)]);commands.value=c;flows.value=f}catch(e){error.value=e.message}finally{loading.value=false}}
function add(){commands.value.push(blank())}function remove(i){commands.value.splice(i,1)}function clean(row){row.command=String(row.command||'').replace(/^\/+/, '').toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,32)}
async function save(){saving.value=true;error.value='';success.value='';try{const payload={commands:commands.value.map(c=>({...c,command:String(c.command||'').replace(/^\/+/,''),flow_id:c.flow_id?Number(c.flow_id):null}))};const result=await req(`/telegram/bots/${botId.value}/commands`,{method:'PUT',body:JSON.stringify(payload)});success.value=`Synced ${result.count} command${result.count===1?'':'s'} to Telegram.`;await load();success.value=`Synced ${result.count} command${result.count===1?'':'s'} to Telegram.`}catch(e){error.value=e.message}finally{saving.value=false}}
onMounted(loadBots)
</script>
<template><div class="commands-page"><header><div><p class="eyebrow">Telegram</p><h2>Bot Commands</h2><p>Manage the commands users see from Telegram's bot menu and optionally route each command into a Buccaneer flow.</p></div><button class="primary" :disabled="saving||!botId" @click="save">{{saving?'Syncing…':'Save & Sync to Telegram'}}</button></header><section class="command-card"><div class="toolbar"><label>Bot<select v-model="botId" @change="load"><option v-for="bot in bots" :key="bot.id" :value="String(bot.id)">@{{bot.username||bot.first_name||bot.bot_id}}</option></select></label><button class="secondary" :disabled="loading||!botId" @click="load">↻ Import from Telegram</button></div><div class="hint"><b>How it works</b><span>The command and description are published to Telegram. Selecting a flow also adds <code>/command</code> to that flow's keyword triggers without removing its existing trigger phrases.</span></div><div v-if="loading" class="empty">Loading Telegram commands…</div><div v-else-if="!bots.length" class="empty">Connect a Telegram bot first.</div><template v-else><div class="head-row"><span>On</span><span>Command</span><span>Description</span><span>Flow</span><span></span></div><div v-for="(row,i) in commands" :key="i" class="command-row"><input v-model="row.enabled" type="checkbox"><label class="command-input"><span>/</span><input v-model="row.command" maxlength="32" placeholder="start" @input="clean(row)"></label><input v-model="row.description" maxlength="256" placeholder="Start or restart"><select v-model="row.flow_id"><option :value="null">No flow</option><option v-for="flow in flows" :key="flow.id" :value="flow.id">{{flow.name}} · {{flow.status}}</option></select><button class="delete" title="Remove command" @click="remove(i)">×</button></div><button class="add" @click="add">+ Add command</button></template><p v-if="success" class="success">{{success}}</p><p v-if="error" class="error">{{error}}</p></section><section class="notes"><strong>Command rules</strong><span>• Up to 100 commands per bot.</span><span>• Command names use lowercase letters, numbers and underscores.</span><span>• Descriptions can be up to 256 characters.</span><span>• Disabled rows stay in Buccaneer's editor until refresh but are not published to Telegram.</span></section></div></template>
<style scoped>.commands-page{max-width:1180px}.commands-page header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:18px}.commands-page h2{margin:2px 0 5px;font-size:24px}.commands-page header p:last-child{margin:0;color:#74867e}.eyebrow{margin:0!important;color:#229ed9!important;text-transform:uppercase;font-size:10px;font-weight:900;letter-spacing:.08em}.primary,.secondary,.add,.delete{cursor:pointer;border-radius:8px;font-weight:800}.primary{border:1px solid #168b65;background:#168b65;color:#fff;padding:10px 14px}.secondary{border:1px solid #d4dfda;background:#fff;color:#29453a;padding:9px 12px}.command-card,.notes{background:#fff;border:1px solid #dce6e2;border-radius:14px;padding:20px;box-shadow:0 3px 14px rgba(21,57,43,.04)}.toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:12px}.toolbar label{display:grid;gap:5px;font-size:11px;font-weight:800}.toolbar select,.command-row input,.command-row select{border:1px solid #d2ded9;border-radius:8px;padding:9px 10px;background:#fff;font:inherit}.toolbar select{min-width:240px}.hint{display:flex;flex-direction:column;gap:3px;margin:15px 0;padding:11px 12px;border-radius:9px;background:#f3faff;color:#607985;font-size:11px}.hint b{color:#23566d}.hint code{color:#1679a8}.head-row,.command-row{display:grid;grid-template-columns:42px minmax(130px,.65fr) minmax(220px,1.2fr) minmax(190px,1fr) 34px;gap:9px;align-items:center}.head-row{padding:8px 4px;color:#7e9088;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.05em}.command-row{padding:8px 4px;border-top:1px solid #edf2ef}.command-row>input[type=checkbox]{width:16px;height:16px}.command-input{display:flex;align-items:center;border:1px solid #d2ded9;border-radius:8px;background:#fff}.command-input span{padding-left:9px;color:#229ed9;font-weight:900}.command-input input{min-width:0;width:100%;border:0!important;outline:0}.delete{width:30px;height:30px;border:1px solid #efd6d6;background:#fff8f8;color:#a83d3d;font-size:18px}.add{margin-top:12px;border:1px dashed #a9d8c1;background:#f5fbf8;color:#177657;padding:9px 12px}.success,.error{padding:10px 12px;border-radius:8px;font-size:11px}.success{background:#edf9f3;color:#177657}.error{background:#fff0f0;color:#9c2929}.empty{padding:30px;text-align:center;color:#7e9088}.notes{margin-top:14px;display:flex;flex-direction:column;gap:5px;color:#71837b;font-size:11px}.notes strong{color:#29483c;margin-bottom:3px}@media(max-width:850px){.commands-page header,.toolbar{flex-direction:column}.head-row{display:none}.command-row{grid-template-columns:32px 1fr 32px}.command-row>input:not([type=checkbox]),.command-row>select,.command-input{grid-column:2}.delete{grid-column:3;grid-row:1}.toolbar select{min-width:0;width:100%}}</style>